//! Roadmap 0.42 S4 (editions page, public prices switched off) and C9 (private sales price
//! sheet), both generated by commercial/tools/prices.py from commercial/prices.toml, the
//! §1c prices the owner approved at gate K4.

use std::path::{Path, PathBuf};
use std::process::Command;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn prices(args: &[&str]) -> (Option<i32>, String) {
    let out = Command::new("python3")
        .arg(root().join("commercial/tools/prices.py"))
        .args(args)
        .output()
        .expect("python3 runs");
    (
        out.status.code(),
        format!(
            "{}{}",
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&out.stderr)
        ),
    )
}

fn read(p: &str) -> String {
    std::fs::read_to_string(root().join(p)).unwrap()
}

#[test]
fn committed_outputs_are_current_and_the_switch_is_off() {
    let (code, out) = prices(&["build", "--check"]);
    assert_eq!(code, Some(0), "{out}");
    let toml: toml::Value = toml::from_str(&read("commercial/prices.toml")).unwrap();
    assert_eq!(
        toml["switch"]["public_prices"].as_bool(),
        Some(false),
        "the public price switch stays off until the owner turns it on"
    );
}

#[test]
fn the_editions_page_shows_no_price_and_sovereign_is_contact_us() {
    let page = read("commercial/editions/editions.html");
    assert!(!page.contains('$'), "no price while the switch is off");
    assert!(page.contains("Kshana Sovereign"));
    assert!(page.contains("Contact us"));
    assert!(page.contains("Free"), "the open edition is free");
    assert!(!page.contains("kshana-private-price-sheet"));
    for word in ["compliant", "conform", "certified"] {
        assert!(!page.to_lowercase().contains(word), "{word}");
    }
}

#[test]
fn the_private_sheet_carries_the_approved_prices() {
    let sheet = read("commercial/sales/PRICE-SHEET.md");
    assert!(sheet.starts_with("<!-- kshana-private-price-sheet: PRIVATE"));
    for p in [
        "$290/month or $2,900/year",
        "$4,900/seat/year",
        "from $45,000/year",
        "$490/seat/year",
        "$4,900 standard; $14,900 claim-grade with expert review",
        "$12,000",
        "$5,900/site/year",
        "$24,000",
        "$3,900",
        "$9,900 + $2,500/year",
        "from $90,000/year",
    ] {
        assert!(sheet.contains(p), "missing {p}");
    }
}

#[test]
fn the_sheet_never_reaches_a_public_tree() {
    // Refused as an output path inside a public tree.
    for p in [
        "site-next/price.md",
        "docs/price.md",
        "commercial/editions/x.md",
    ] {
        let (code, out) = prices(&["sheet", "--out", &root().join(p).to_string_lossy()]);
        assert_eq!(code, Some(2), "{p}: {out}");
        assert!(!root().join(p).exists());
    }
    // This repository's public trees carry no private price.
    let (code, out) = prices(&[
        "scan-public",
        &root().join("site-next").to_string_lossy(),
        &root().join("commercial/editions").to_string_lossy(),
    ]);
    assert_eq!(code, Some(0), "{out}");
    // A copied sheet, or one price from it, is caught.
    let d =
        Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("price-scan-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(&d).unwrap();
    std::fs::write(d.join("a.html"), "<p>Sovereign from $90,000/year</p>").unwrap();
    let (code, out) = prices(&["scan-public", &d.to_string_lossy()]);
    assert_eq!(code, Some(1), "{out}");
    std::fs::write(d.join("a.html"), "<p>Pro: $290/month or $2,900/year</p>").unwrap();
    assert_eq!(prices(&["scan-public", &d.to_string_lossy()]).0, Some(1));
    std::fs::write(d.join("a.html"), "<p>Kshana Pro. Contact us.</p>").unwrap();
    assert_eq!(prices(&["scan-public", &d.to_string_lossy()]).0, Some(0));
    let _ = std::fs::remove_dir_all(&d);
}

#[test]
fn a_price_list_without_a_private_sovereign_is_refused() {
    let d =
        Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("price-bad-{}", std::process::id()));
    std::fs::create_dir_all(&d).unwrap();
    let bad = read("commercial/prices.toml").replace(
        "# Sovereign is never priced in public (owner): \"Contact us\" on every public page.\npublic = false",
        "public = true",
    );
    assert_ne!(bad, read("commercial/prices.toml"));
    let f = d.join("prices.toml");
    std::fs::write(&f, bad).unwrap();
    let (code, out) = prices(&["--prices", &f.to_string_lossy(), "build", "--check"]);
    assert_eq!(code, Some(2), "{out}");
    assert!(out.contains("Sovereign"));
}
